Given a number, the task is to check if a number is divisible by 6 or not. The input number may be large and it may not be possible to store even if we use long long int.Examples: Input  : n = 2112Output: YesInput : n = 1124Output : NoInput  : n = 363588395960667043875487Output : No
            C++

    #include <iostream>
using namespace std;

int main() {

    long n = 36358839596;

      // finding given number is divisible by 6 or not
    if (n % 6 == 0)
        cout << "Yes";
    else
        cout << "No";
    return 0;
}

