OutputNoTime complexity: O(1) as it is performing constant operationsAuxiliary Space: O(1) as it is using constant space for variablesSince input number may be very large, we cannot use n % 6 to check if a number is divisible by 6 or not, especially in languages like C/C++. The idea is based on following fact. A number is divisible by 6 it's divisible by 2 and 3. a)  A number is divisible by 2 if its last digit is divisible by 2.b)  A number is divisible by 3 if sum of digits is divisible by 3.Below is the implementation based on above steps. 
            C++

    // C++ program to find if a number is divisible by
// 6 or not
#include<bits/stdc++.h>
using namespace std;

// Function to find that number divisible by 6 or not
bool check(string str)
{
    int n = str.length();

    // Return false if number is not divisible by 2.
    if ((str[n-1]-'0')%2 != 0)
       return false;

    // If we reach here, number is divisible by 2.
    // Now check for 3.

    // Compute sum of digits
    int digitSum = 0;
    for (int i=0; i<n; i++)
        digitSum += (str[i]-'0');

    // Check if sum of digits is divisible by 3
    return (digitSum % 3 == 0);
}

// Driver code
int main()
{
    string str = "1332";
    check(str)?  cout << "Yes" : cout << "No ";
    return 0;
}


            Java

    // Java program to find if a number is
// divisible by 6 or not
import java.io.*;
class IsDivisible
{
    // Function to find that number divisible by 6 or not
    static boolean check(String str)
    {
        int n = str.length();

        // Return false if number is not divisible by 2.
        if ((str.charAt(n-1) -'0')%2 != 0)
           return false;

        // If we reach here, number is divisible by 2.
        // Now check for 3.

        // Compute sum of digits
        int digitSum = 0;
        for (int i=0; i<n; i++)
            digitSum += (str.charAt(i)-'0');

        // Check if sum of digits is divisible by 3
        return (digitSum % 3 == 0);
    }

    // main function
    public static void main (String[] args) 
    {
        String str = "1332";
        if(check(str))
            System.out.println("Yes");
        else
            System.out.println("No");
    }
} 


